actions.script:
function clean(v) { return (v || '').trim(); }
function toNum(v) {
    if (v == null) return 0;
    if (typeof v === 'number') return v;
    if (typeof v.toNumber === 'function') return v.toNumber();
    return parseFloat(String(v)) || 0;
}
function escapeXml(str) {
    if (!str) return '';
    return String(str).replace(/&/g, '&amp;')
                      .replace(/</g, '&lt;')
                      .replace(/>/g, '&gt;')
                      .replace(/"/g, '&quot;')
                      .replace(/'/g, '&apos;');
}
function format2(num) {
    return toNum(num).toFixed(2);
}

// From Party details
const fromVatRaw = fromTaxList?.[0]?.partyTaxId || fromTaxList?.[0]?.taxIdNumber || '';
const fromVat = fromVatRaw.replace(/^IT/i, '');
const fromSsn = fromIdents.find(p => p.partyIdTypeEnumId === 'PtidSsn')?.idValue || fromVat;
const fromRea = fromIdents.find(p => p.partyIdTypeEnumId === 'PtidREA')?.idValue || '';
const fromName = fromOrg?.organizationName || invoice.fromPartyId;
const fromAddr = fromAddresses?.[0] || {};

// To Party details
const toVatRaw = toTaxList?.[0]?.partyTaxId || toTaxList?.[0]?.taxIdNumber || '';
const toVat = toVatRaw.replace(/^IT/i, '');
const toSsn = toIdents.find(p => p.partyIdTypeEnumId === 'PtidSsn')?.idValue || toVat;
const toSdi = toIdents.find(p => p.partyIdTypeEnumId === 'PtidExchSysCode')?.idValue || '0000000';
const toPec = toIdents.find(p => p.partyIdTypeEnumId === 'PtidPec')?.idValue || '';
const toName = toOrg?.organizationName || invoice.toPartyId;
const toAddr = toAddresses?.[0] || {};

// Document type determination
let td = invoice.electronicInvoiceTypeEnumId;
if (!td) {
    if (invoice.invoiceTypeEnumId === 'InvoiceCreditMemo' || invoice.invoiceTypeEnumId === 'InvoiceReturn') {
        td = 'TD04';
    } else if (shipmentSources && shipmentSources.length > 0) {
        td = 'TD24';
    } else {
        td = 'TD01';
    }
}
context.tipoDocumento = td;

// Format: auto-detect FPA12 for Public Administration (6-char IPA code) vs FPR12 (B2B/B2C)
let format = formatoTrasmissione;
if (!format || format === 'FPR12') {
    if (toSdi && toSdi.length === 6 && toSdi !== '000000') {
        format = 'FPA12';
    } else {
        format = 'FPR12';
    }
}

// Dates & sequence
const invDate = invoice.invoiceDate ? ec.l10n.format(invoice.invoiceDate, 'yyyy-MM-dd') : ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd');
const invNumber = invoice.referenceNumber || invoice.invoiceId;
const progInvio = progressivoInvio || String(invoice.invoiceId).padStart(5, '0');
const fileId = (fromVat || '00000000000') + '_' + progInvio.slice(-5);
const sdiFilename = 'IT' + fileId + '.xml';
context.filename = sdiFilename;
context.formatoTrasmissione = format;

// Process lines & VAT summary
const taxTypes = ['ItemSalesTax', 'ItemVatTax', 'ItemVatTaxTotal', 'ItemTax'];
const goodsItems = (items || []).filter(item => !taxTypes.includes(item.itemTypeEnumId));
const taxItems = (items || []).filter(item => taxTypes.includes(item.itemTypeEnumId));

// Predominant or default tax rate from calculated tax lines
let defaultTaxRate = 22.0;
let defaultNature = '';
if (taxItems.length > 0) {
    const firstTax = taxItems[0];
    defaultTaxRate = toNum(firstTax.taxPercentage) || 0;
    defaultNature = firstTax.vatNatureEnumId || (defaultTaxRate === 0 ? 'N4' : '');
}

const lines = [];
const seqToLineNum = {};
const vatSummary = {};
let totalWithholding = 0;
let withholdingType = null;
let withholdingRate = 0;
let withholdingReason = 'A';
let lineSeq = 1;

const resolveNatureCode = (raw) => {
    if (!raw) return '';
    if (/^N[1-7](\.[0-9])?$/.test(raw)) return raw;
    const enumRec = ec.entity.find('moqui.basic.Enumeration').condition('enumId', raw).useCache(true).one();
    return enumRec?.enumCode || raw;
};
const resolveCountryAlpha2 = (geoId) => {
    if (!geoId || geoId === 'ITA') return 'IT';
    const geoRec = ec.entity.find('moqui.basic.Geo').condition('geoId', geoId).useCache(true).one();
    return geoRec?.geoCodeAlpha2 || (geoId.length === 2 ? geoId : 'IT');
};
const resolveProvinceCode = (geoId) => {
    if (!geoId) return '';
    const geoRec = ec.entity.find('moqui.basic.Geo').condition('geoId', geoId).useCache(true).one();
    if (geoRec?.geoCodeAlpha2) return geoRec.geoCodeAlpha2.slice(0, 2);
    return geoId.replace(/^ITA_/, '').slice(0, 2);
};
defaultNature = resolveNatureCode(defaultNature);

for (const item of goodsItems) {
    const qty = toNum(item.quantity) || 1;
    const price = toNum(item.amount) || 0;
    const lineTotal = toNum(item.lineTotal) || (qty * price);
    let rate = item.taxPercentage != null ? toNum(item.taxPercentage) : defaultTaxRate;
    let nature = resolveNatureCode(item.vatNatureEnumId) || (rate === 0 ? (defaultNature || 'N4') : '');

    if (item.withholdingTaxTypeEnumId) {
        withholdingType = item.withholdingTaxTypeEnumId;
        withholdingRate = toNum(item.withholdingTaxRate) || 20.0;
        if (item.withholdingPaymentReason) withholdingReason = item.withholdingPaymentReason;
        totalWithholding += (lineTotal * withholdingRate / 100);
    }

    const curLineNum = lineSeq++;
    seqToLineNum[item.invoiceItemSeqId] = curLineNum;
    let uomCode = '';
    if (item.quantityUomId) {
        if (item.quantityUomId === 'OTH_ea') uomCode = 'PZ';
        else {
            const uomRec = ec.entity.find('moqui.basic.Uom').condition('uomId', item.quantityUomId).useCache(true).one();
            uomCode = uomRec?.abbreviation || item.quantityUomId;
        }
    }

    lines.push({
        lineNum: curLineNum,
        desc: item.description || ('Item ' + item.invoiceItemSeqId),
        qty: qty,
        uom: uomCode,
        price: price,
        lineTotal: lineTotal,
        vatRate: rate,
        vatNature: nature
    });

    const key = format2(rate) + '_' + nature;
    if (!vatSummary[key]) {
        vatSummary[key] = { rate: rate, nature: nature, taxable: 0, tax: 0 };
    }
    vatSummary[key].taxable += lineTotal;
}

// If taxItems specify actual calculated tax amount, use it for vatSummary
for (const k in vatSummary) {
    const rate = vatSummary[k].rate;
    if (rate > 0) {
        const matchingTax = taxItems.find(t => Math.abs(toNum(t.taxPercentage) - rate) < 0.01);
        if (matchingTax && toNum(matchingTax.amount) > 0) {
            vatSummary[k].tax = toNum(matchingTax.amount);
        } else {
            vatSummary[k].tax = vatSummary[k].taxable * rate / 100;
        }
    }
}

// If no goods items, generate a fallback line
if (lines.length === 0) {
    const fallbackAmt = toNum(invoice.invoiceTotal) || 0;
    lines.push({
        lineNum: 1,
        desc: invoice.description || ('Invoice ' + invNumber),
        qty: 1,
        price: fallbackAmt,
        lineTotal: fallbackAmt,
        vatRate: 22.0,
        vatNature: ''
    });
    vatSummary['22.00_'] = { rate: 22.0, nature: '', taxable: fallbackAmt, tax: fallbackAmt * 0.22 };
}

let sumTaxable = 0;
let sumTax = 0;
for (const k in vatSummary) {
    sumTaxable += vatSummary[k].taxable;
    sumTax += vatSummary[k].tax;
}
const docTotal = sumTaxable + sumTax;
context.invoiceTotal = docTotal;

// Build XML Output
let xml = '<?xml version="1.0" encoding="UTF-8"?>\n';
xml += '<p:FatturaElettronica versione="' + format + '"\n';
xml += '    xmlns:ds="http://www.w3.org/2000/09/xmldsig#"\n';
xml += '    xmlns:p="http://ivaservizi.agenziaentrate.gov.it/docs/xsd/fatture/v1.2"\n';
xml += '    xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"\n';
xml += '    xsi:schemaLocation="http://ivaservizi.agenziaentrate.gov.it/docs/xsd/fatture/v1.2 http://www.fatturapa.gov.it/export/fatturapa/sdi/fatturapa/v1.2/Schema_del_flusso_FatturaPA_v1.2.xsd">\n';

// 1. Header
xml += '  <FatturaElettronicaHeader>\n';
xml += '    <DatiTrasmissione>\n';
xml += '      <IdTrasmittente>\n';
xml += '        <IdPaese>IT</IdPaese>\n';
xml += '        <IdCodice>' + escapeXml(fromVat || fromSsn) + '</IdCodice>\n';
xml += '      </IdTrasmittente>\n';
xml += '      <ProgressivoInvio>' + escapeXml(progInvio) + '</ProgressivoInvio>\n';
xml += '      <FormatoTrasmissione>' + escapeXml(format) + '</FormatoTrasmissione>\n';
xml += '      <CodiceDestinatario>' + escapeXml(toSdi || '0000000') + '</CodiceDestinatario>\n';
if (toPec && toSdi === '0000000') {
    xml += '      <PECDestinatario>' + escapeXml(toPec) + '</PECDestinatario>\n';
}
xml += '    </DatiTrasmissione>\n';

// CedentePrestatore
xml += '    <CedentePrestatore>\n';
xml += '      <DatiAnagrafici>\n';
if (fromVat) {
    xml += '        <IdFiscaleIVA>\n';
    xml += '          <IdPaese>IT</IdPaese>\n';
    xml += '          <IdCodice>' + escapeXml(fromVat) + '</IdCodice>\n';
    xml += '        </IdFiscaleIVA>\n';
}
if (fromSsn) {
    xml += '        <CodiceFiscale>' + escapeXml(fromSsn) + '</CodiceFiscale>\n';
}
xml += '        <Anagrafica>\n';
xml += '          <Denominazione>' + escapeXml(fromName) + '</Denominazione>\n';
xml += '        </Anagrafica>\n';
xml += '        <RegimeFiscale>RF01</RegimeFiscale>\n';
xml += '      </DatiAnagrafici>\n';
const fromCountry = resolveCountryAlpha2(fromAddr.countryGeoId);
const fromProv = resolveProvinceCode(fromAddr.stateProvinceGeoId);
xml += '      <Sede>\n';
xml += '        <Indirizzo>' + escapeXml(fromAddr.address1 || '-') + '</Indirizzo>\n';
xml += '        <CAP>' + escapeXml(fromAddr.postalCode || '00000') + '</CAP>\n';
xml += '        <Comune>' + escapeXml(fromAddr.city || '-') + '</Comune>\n';
if (fromProv) {
    xml += '        <Provincia>' + escapeXml(fromProv) + '</Provincia>\n';
}
xml += '        <Nazione>' + escapeXml(fromCountry) + '</Nazione>\n';
xml += '      </Sede>\n';
if (fromRea) {
    xml += '      <IscrizioneREA>\n';
    xml += '        <Ufficio>' + escapeXml(fromRea.split('-')[0] || 'MI') + '</Ufficio>\n';
    xml += '        <NumeroREA>' + escapeXml(fromRea.split('-')[1] || fromRea) + '</NumeroREA>\n';
    xml += '        <StatoLiquidazione>LN</StatoLiquidazione>\n';
    xml += '      </IscrizioneREA>\n';
}
xml += '    </CedentePrestatore>\n';

// CessionarioCommittente
const toCountry = resolveCountryAlpha2(toAddr.countryGeoId);
const toProv = resolveProvinceCode(toAddr.stateProvinceGeoId);
xml += '    <CessionarioCommittente>\n';
xml += '      <DatiAnagrafici>\n';
if (toVat) {
    xml += '        <IdFiscaleIVA>\n';
    xml += '          <IdPaese>' + escapeXml(toCountry) + '</IdPaese>\n';
    xml += '          <IdCodice>' + escapeXml(toVat) + '</IdCodice>\n';
    xml += '        </IdFiscaleIVA>\n';
}
if (toSsn) {
    xml += '        <CodiceFiscale>' + escapeXml(toSsn) + '</CodiceFiscale>\n';
}
xml += '        <Anagrafica>\n';
xml += '          <Denominazione>' + escapeXml(toName) + '</Denominazione>\n';
xml += '        </Anagrafica>\n';
xml += '      </DatiAnagrafici>\n';
xml += '      <Sede>\n';
xml += '        <Indirizzo>' + escapeXml(toAddr.address1 || '-') + '</Indirizzo>\n';
xml += '        <CAP>' + escapeXml(toAddr.postalCode || '00000') + '</CAP>\n';
xml += '        <Comune>' + escapeXml(toAddr.city || '-') + '</Comune>\n';
if (toProv) {
    xml += '        <Provincia>' + escapeXml(toProv) + '</Provincia>\n';
}
xml += '        <Nazione>' + escapeXml(toCountry) + '</Nazione>\n';
xml += '      </Sede>\n';
xml += '    </CessionarioCommittente>\n';
xml += '  </FatturaElettronicaHeader>\n';

// 2. Body
xml += '  <FatturaElettronicaBody>\n';
xml += '    <DatiGenerali>\n';
xml += '      <DatiGeneraliDocumento>\n';
xml += '        <TipoDocumento>' + escapeXml(td) + '</TipoDocumento>\n';
xml += '        <Divisa>' + escapeXml(invoice.currencyUomId || 'EUR') + '</Divisa>\n';
xml += '        <Data>' + invDate + '</Data>\n';
xml += '        <Numero>' + escapeXml(invNumber) + '</Numero>\n';

if (totalWithholding > 0 && withholdingType) {
    xml += '        <DatiRitenuta>\n';
    xml += '          <TipoRitenuta>' + escapeXml(withholdingType) + '</TipoRitenuta>\n';
    xml += '          <ImportoRitenuta>' + format2(totalWithholding) + '</ImportoRitenuta>\n';
    xml += '          <AliquotaRitenuta>' + format2(withholdingRate) + '</AliquotaRitenuta>\n';
    xml += '          <CausalePagamento>' + escapeXml(withholdingReason) + '</CausalePagamento>\n';
    xml += '        </DatiRitenuta>\n';
}

xml += '        <ImportoTotaleDocumento>' + format2(docTotal) + '</ImportoTotaleDocumento>\n';
xml += '      </DatiGeneraliDocumento>\n';

// DatiDDT (Transport documents for shipments / deferred invoices TD24)
const ddtMap = {};
for (const s of (shipmentSources || [])) {
    if (s.shipmentId) {
        if (!ddtMap[s.shipmentId]) ddtMap[s.shipmentId] = [];
        if (s.invoiceItemSeqId) ddtMap[s.shipmentId].push(s.invoiceItemSeqId);
    }
}
for (const shipId in ddtMap) {
    const ship = ec.entity.find('mantle.shipment.Shipment').condition('shipmentId', shipId).one();
    if (ship) {
        const ddtDate = ship.estimatedShipDate || ship.entryDate || invoice.invoiceDate;
        const ddtDateStr = ec.l10n.format(ddtDate, 'yyyy-MM-dd');
        xml += '      <DatiDDT>\n';
        xml += '        <NumeroDDT>' + escapeXml(ship.trackingNumber || ship.shipmentId) + '</NumeroDDT>\n';
        xml += '        <DataDDT>' + ddtDateStr + '</DataDDT>\n';
        for (const lineSeq of ddtMap[shipId]) {
            const mappedLineNum = seqToLineNum[lineSeq];
            if (mappedLineNum != null) {
                xml += '        <RiferimentoNumeroLinea>' + mappedLineNum + '</RiferimentoNumeroLinea>\n';
            }
        }
        xml += '      </DatiDDT>\n';
    }
}

xml += '    </DatiGenerali>\n';

// Line items
xml += '    <DatiBeniServizi>\n';
for (const l of lines) {
    xml += '      <DettaglioLinee>\n';
    xml += '        <NumeroLinea>' + l.lineNum + '</NumeroLinea>\n';
    xml += '        <Descrizione>' + escapeXml(l.desc) + '</Descrizione>\n';
    xml += '        <Quantita>' + format2(l.qty) + '</Quantita>\n';
    if (l.uom) {
        xml += '        <UnitaMisura>' + escapeXml(l.uom) + '</UnitaMisura>\n';
    }
    xml += '        <PrezzoUnitario>' + format2(l.price) + '</PrezzoUnitario>\n';
    xml += '        <PrezzoTotale>' + format2(l.lineTotal) + '</PrezzoTotale>\n';
    xml += '        <AliquotaIVA>' + format2(l.vatRate) + '</AliquotaIVA>\n';
    if (l.vatRate === 0 && l.vatNature) {
        xml += '        <Natura>' + escapeXml(l.vatNature) + '</Natura>\n';
    }
    if (withholdingType) {
        xml += '        <Ritenuta>SI</Ritenuta>\n';
    }
    xml += '      </DettaglioLinee>\n';
}

// VAT Summary
const esigibilita = invoice.taxExigibilityEnumId || (format === 'FPA12' ? 'S' : 'I');
for (const k in vatSummary) {
    const row = vatSummary[k];
    xml += '      <DatiRiepilogo>\n';
    xml += '        <AliquotaIVA>' + format2(row.rate) + '</AliquotaIVA>\n';
    if (row.rate === 0 && row.nature) {
        xml += '        <Natura>' + escapeXml(row.nature) + '</Natura>\n';
    }
    xml += '        <ImponibileImporto>' + format2(row.taxable) + '</ImponibileImporto>\n';
    xml += '        <Imposta>' + format2(row.tax) + '</Imposta>\n';
    xml += '        <EsigibilitaIVA>' + escapeXml(esigibilita) + '</EsigibilitaIVA>\n';
    xml += '      </DatiRiepilogo>\n';
}
xml += '    </DatiBeniServizi>\n';

// Payment details
let mpCode = 'MP05';
if (invoice.paymentMethodId) {
    const pm = ec.entity.find('mantle.account.method.PaymentMethod').condition('paymentMethodId', invoice.paymentMethodId).one();
    const pmt = pm?.paymentMethodTypeEnumId || '';
    if (pmt === 'PmtCash') mpCode = 'MP01';
    else if (pmt === 'PmtCompanyCheck' || pmt === 'PmtPersonalCheck') mpCode = 'MP02';
    else if (pmt === 'PmtCreditCard' || pmt === 'PmtDebitCard') mpCode = 'MP08';
    else if (pmt === 'PmtAch') mpCode = 'MP19';
}
const payableAmt = esigibilita === 'S' ? (sumTaxable - totalWithholding) : (docTotal - totalWithholding);
xml += '    <DatiPagamento>\n';
xml += '      <CondizioniPagamento>TP02</CondizioniPagamento>\n';
xml += '      <DettaglioPagamento>\n';
xml += '        <ModalitaPagamento>' + mpCode + '</ModalitaPagamento>\n';
const dueDt = invoice.dueDate ? ec.l10n.format(invoice.dueDate, 'yyyy-MM-dd') : invDate;
xml += '        <DataScadenzaPagamento>' + dueDt + '</DataScadenzaPagamento>\n';
xml += '        <ImportoPagamento>' + format2(payableAmt) + '</ImportoPagamento>\n';
xml += '      </DettaglioPagamento>\n';
xml += '    </DatiPagamento>\n';

xml += '  </FatturaElettronicaBody>\n';
xml += '</p:FatturaElettronica>\n';

context.xmlText = xml;

service-call.in-map:
{
                invoiceId: invoiceId,
                sdiStatusEnumId: 'SdiGenerated',
                sdiFilename: filename,
                electronicInvoiceTypeEnumId: tipoDocumento
            }

actions.script:
let targetStatus = null;
if (notificationTypeEnumId === 'RC') targetStatus = 'SdiDelivered';
else if (notificationTypeEnumId === 'NS') targetStatus = 'SdiRejected';
else if (notificationTypeEnumId === 'MC') targetStatus = 'SdiUndelivered';
else if (notificationTypeEnumId === 'EC' || notificationTypeEnumId === 'DT') targetStatus = 'SdiAccepted';
context.targetStatus = targetStatus;

service-call.in-map:
{
                    invoiceId: invoiceId,
                    sdiStatusEnumId: targetStatus,
                    sdiIdent: sdiIdent || invoice?.sdiIdent,
                    sdiReceiptDate: notifDate
                }

actions.script:
const xml = String(xmlText || '');
const tagVal = (block, tag) => {
    if (!block) return '';
    const re = new RegExp('<(?:[a-zA-Z0-9_-]+:)?' + tag + '[^>]*>([\\s\\S]*?)</(?:[a-zA-Z0-9_-]+:)?' + tag + '>', 'i');
    const m = block.match(re);
    return m ? m[1].replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").trim() : '';
};
const allBlocks = (block, tag) => {
    if (!block) return [];
    const re = new RegExp('<(?:[a-zA-Z0-9_-]+:)?' + tag + '(?:\\s[^>]*)?>([\\s\\S]*?)</(?:[a-zA-Z0-9_-]+:)?' + tag + '>', 'gi');
    const out = [];
    let m;
    while ((m = re.exec(block)) !== null) out.push(m[1]);
    return out;
};

const cedente = tagVal(xml, 'CedentePrestatore');
if (!cedente) {
    ec.message.addError("Invalid FatturaPA XML: missing CedentePrestatore.");
    return;
}
const supVat = tagVal(tagVal(cedente, 'IdFiscaleIVA'), 'IdCodice').replace(/^IT/i, '');
const supCf = tagVal(cedente, 'CodiceFiscale') || supVat;
const supName = tagVal(cedente, 'Denominazione')
    || ((tagVal(cedente, 'Nome') + ' ' + tagVal(cedente, 'Cognome')).trim())
    || supVat || supCf || 'Imported Supplier';

// Match existing supplier by TaxAuthorityParty or PartyIdentification
let supplierPartyId = null;
if (supVat) {
    const tap = ec.entity.find('mantle.other.tax.TaxAuthorityParty')
        .condition('partyTaxId', supVat).list() || [];
    if (tap.length > 0) supplierPartyId = tap[0].partyId;
}
if (!supplierPartyId && supCf) {
    const pi = ec.entity.find('mantle.party.PartyIdentification')
        .condition('idValue', supCf).list() || [];
    if (pi.length > 0) supplierPartyId = pi[0].partyId;
}
if (!supplierPartyId) {
    const supOut = ec.service.sync().name('mantle.party.PartyServices.create#Organization').parameters({
        organizationName: supName,
        roleTypeId: 'Vendor'
    }).call();
    supplierPartyId = supOut.partyId;
    if (supCf) {
        ec.service.sync().name('create#mantle.party.PartyIdentification').parameters({
            partyId: supplierPartyId, partyIdTypeEnumId: 'PtidSsn', idValue: supCf
        }).call();
    }
    if (supVat) {
        ec.service.sync().name('create#mantle.other.tax.TaxAuthorityParty').parameters({
            taxAuthorityId: 'IT_ADE', partyId: supplierPartyId,
            fromDate: ec.user.nowTimestamp, partyTaxId: supVat
        }).call();
    }
    const sede = tagVal(cedente, 'Sede');
    if (sede) {
        ec.service.sync().name('mantle.party.ContactServices.create#PostalAddress').parameters({
            partyId: supplierPartyId,
            contactMechPurposeId: 'PostalPrimary',
            address1: tagVal(sede, 'Indirizzo') || '-',
            postalCode: tagVal(sede, 'CAP') || '00000',
            city: tagVal(sede, 'Comune') || '-',
            countryGeoId: tagVal(sede, 'Nazione') === 'IT' ? 'ITA' : null
        }).call();
    }
}
context.supplierPartyId = supplierPartyId;

const docGen = tagVal(xml, 'DatiGeneraliDocumento');
const td = tagVal(docGen, 'TipoDocumento') || 'TD01';
const divisa = tagVal(docGen, 'Divisa') || 'EUR';
const dataStr = tagVal(docGen, 'Data');
const numero = tagVal(docGen, 'Numero') || 'IMP-' + Date.now();
const invDateTs = dataStr ? ec.l10n.parseTimestamp(dataStr + ' 00:00:00', 'yyyy-MM-dd HH:mm:ss') : ec.user.nowTimestamp;
const invoiceTypeEnumId = (td === 'TD04') ? 'InvoiceCreditMemo' : 'InvoiceSales';

const invOut = ec.service.sync().name('mantle.account.InvoiceServices.create#Invoice').parameters({
    fromPartyId: supplierPartyId,
    toPartyId: organizationPartyId,
    invoiceTypeEnumId: invoiceTypeEnumId,
    statusId: 'InvoiceIncoming',
    currencyUomId: divisa,
    invoiceDate: invDateTs,
    referenceNumber: numero,
    electronicInvoiceTypeEnumId: td,
    sdiStatusEnumId: 'SdiReceived'
}).call();
const invoiceId = invOut.invoiceId;
context.invoiceId = invoiceId;

let itemCount = 0;
const lines = allBlocks(xml, 'DettaglioLinee');
for (const line of lines) {
    const desc = tagVal(line, 'Descrizione') || 'Imported Line';
    const qty = parseFloat(tagVal(line, 'Quantita') || '1') || 1;
    const price = parseFloat(tagVal(line, 'PrezzoUnitario') || tagVal(line, 'PrezzoTotale') || '0') || 0;
    const vatRate = parseFloat(tagVal(line, 'AliquotaIVA') || '0') || 0;
    ec.service.sync().name('mantle.account.InvoiceServices.create#InvoiceItem').parameters({
        invoiceId: invoiceId,
        itemTypeEnumId: 'ItemExpense',
        description: desc.slice(0, 250),
        quantity: toDecimal(qty),
        amount: toDecimal(price).setScale(2, 'HALF_UP'),
        taxPercentage: toDecimal(vatRate)
    }).call();
    itemCount++;
}

const riepiloghi = allBlocks(xml, 'DatiRiepilogo');
let totalVat = 0;
for (const riep of riepiloghi) {
    const rate = parseFloat(tagVal(riep, 'AliquotaIVA') || '0') || 0;
    const imposta = parseFloat(tagVal(riep, 'Imposta') || '0') || 0;
    const natura = tagVal(riep, 'Natura');
    if (imposta !== 0 || natura) {
        ec.service.sync().name('mantle.account.InvoiceServices.create#InvoiceItem').parameters({
            invoiceId: invoiceId,
            itemTypeEnumId: 'ItemVatTaxTotal',
            taxAuthorityId: 'IT_ADE',
            description: 'VAT ' + rate + '%' + (natura ? ' (' + natura + ')' : ''),
            quantity: toDecimal(1),
            amount: toDecimal(imposta).setScale(2, 'HALF_UP'),
            taxPercentage: toDecimal(rate),
            vatNatureEnumId: natura || null
        }).call();
        itemCount++;
    }
    totalVat += imposta;
}

const invRec = ec.entity.find('mantle.account.invoice.Invoice').condition('invoiceId', invoiceId).one();
context.itemCount = itemCount;
context.totalAmount = invRec?.invoiceTotal || toDecimal(0);

const xml = String(xmlText || '');
const tagVal = (block, tag) => {
    const re = new RegExp('<(?:[a-zA-Z0-9_-]+:)?' + tag + '[^>]*>([\\s\\S]*?)</(?:[a-zA-Z0-9_-]+:)?' + tag + '>', 'i');
    const m = block.match(re);
    return m ? m[1].trim() : '';
};
let notifType = 'RC';
if (/NotificaScarto/i.test(xml)) notifType = 'NS';
else if (/NotificaMancataConsegna/i.test(xml)) notifType = 'MC';
else if (/NotificaDecorrenzaTermini/i.test(xml)) notifType = 'DT';
else if (/NotificaEsito/i.test(xml)) notifType = 'EC';
else if (/RicevutaConsegna/i.test(xml)) notifType = 'RC';

context.notificationTypeEnumId = notifType;
context.sdiIdent = tagVal(xml, 'IdentificativoSdI');
context.fileLocation = tagVal(xml, 'NomeFile');
context.description = tagVal(xml, 'Descrizione') || tagVal(xml, 'Esito') || notifType;
